INSERT INTO `emails` (`id`, `sender`, `recipient`, `subject`, `body_text`, `body_html`, `raw_headers`, `submitted_at`, `ip_address`, `language`) VALUES
(1, 'no-reply@microsoft-security.top', NULL, 'Your password will expire in 24 hours', 'Dear Microsoft User,\n\nYour Microsoft account password will expire in 24 hours. To keep your account active, please update your password immediately.\n\nUpdate Password: http://192.168.50.1/microsoft/reset?user=you@email.com\n\nIf you do not update your password, your account will be permanently deactivated.\n\nMicrosoft Account Team.', NULL, '{\'from\': \'Microsoft Account Team <no-reply@microsoft-security.top>\', \'subject\': \'Your password will expire in 24 hours\'}', '2026-05-13 19:31:04', '127.0.0.1', 'en'),
(2, 'recruitment@jobs-africa-careers.com', NULL, 'Exciting Job Opportunity - Earn $5,000/month Working From Home', 'Hello,\n\nWe found your profile online and believe you are a great candidate for our data entry position. Earn $5,000 per month working from home, no experience required!\n\nRequirements:\n- Must have a bank account\n- Available 2 hours per day\n\nTo apply, visit: http://bit.ly/afr-jobs-2024\n\nReply to this email with your details.\n\nHR Department', NULL, '{\'from\': \'recruitment@jobs-africa-careers.com\', \'subject\': \'Exciting Job Opportunity - Earn $5,000/month Working From Home\'}', '2026-05-13 19:33:10', '127.0.0.1', 'en'),
