(10, 'registrar@udsm.ac.tz', NULL, 'Course Registration Confirmation - Semester 1 2024/2025', 'Dear John Msangi,\n\nYour course registration for Semester 1, 2024/2025 academic year has been successfully processed. Below are your registered courses:\n\n1. CS 401 - Software Engineering (3 Credits)\n2. CS 405 - Database Systems (3 Credits)\n3. CS 412 - Computer Networks (3 Credits)\n\nYour student portal is available at: https://portal.udsm.ac.tz\n\nIf you have any questions, contact the Registrar\'s Office:\nEmail: registrar@udsm.ac.tz\nPhone: +255 22 241 0500\n\nBest regards,\nUniversity of Dar es Salaam\nRegistrar\'s Office', NULL, '{\'from\': \'registrar@udsm.ac.tz\', \'subject\': \'Course Registration Confirmation - Semester 1 2024/2025\'}', '2026-05-13 19:40:26', '127.0.0.1', 'en'),
(11, 'registrar@udsm.ac.tz', NULL, 'Course Registration Confirmation - Semester 1 2024/2025', 'Dear John Msangi,\n\nYour course registration for Semester 1, 2024/2025 academic year has been successfully processed. Below are your registered courses:\n\n1. CS 401 - Software Engineering (3 Credits)\n2. CS 405 - Database Systems (3 Credits)\n3. CS 412 - Computer Networks (3 Credits)\n\nYour student portal is available at: https://portal.udsm.ac.tz\n\nIf you have any questions, contact the Registrar\'s Office:\nEmail: registrar@udsm.ac.tz\nPhone: +255 22 241 0500\n\nBest regards,\nUniversity of Dar es Salaam\nRegistrar\'s Office', NULL, '{\'from\': \'registrar@udsm.ac.tz\', \'subject\': \'Course Registration Confirmation - Semester 1 2024/2025\'}', '2026-05-13 19:52:32', '127.0.0.1', 'en'),
(32, 'security@crdb-verify.xyz', '', 'URGENT: Your CRDB account has been suspended', 'Dear Customer,\n\nYour CRDB Bank account has been SUSPENDED due to suspicious activity. You must verify your account immediately or it will be permanently closed.\n\nClick here to verify: http://crdb-secure-login.tk/verify?token=abc123\n\nPlease provide your:\n- Account number\n- PIN number\n- Date of birth\n\nYou have 24 hours to act or your account will be deleted.\n\nCRDB Bank Security Team', '', '{\'from\': \'CRDB Bank Security <security@crdb-verify.xyz>\', \'subject\': \'URGENT: Your CRDB account has been suspended\'}', '2026-05-14 03:32:42', '127.0.0.1', 'en'),
(33, 'registrar@udsm.ac.tz', '', 'Course Registration Confirmation - Semester 1 2024/2025', 'Dear John Msangi,\n\nYour course registration for Semester 1, 2024/2025 academic year has been successfully processed. Below are your registered courses:\n\n1. CS 401 - Software Engineering (3 Credits)\n2. CS 405 - Database Systems (3 Credits)\n3. CS 412 - Computer Networks (3 Credits)\n\nYour student portal is available at: https://portal.udsm.ac.tz\n\nIf you have any questions, contact the Registrar\'s Office:\nEmail: registrar@udsm.ac.tz\nPhone: +255 22 241 0500\n\nBest regards,\nUniversity of Dar es Salaam\nRegistrar\'s Office', '', '{\'from\': \'registrar@udsm.ac.tz\', \'subject\': \'Course Registration Confirmation - Semester 1 2024/2025\'}', '2026-05-14 03:34:00', '127.0.0.1', 'en'),
(34, '[alerts@crdbbank.co.tz](mailto:alerts@crdbbank.co.tz)', '', '', 'To: [customer@gmail.com](mailto:customer@gmail.com)\n\nSubject: CRDB Bank Transaction Alert\n\nDear Customer,\n\nA withdrawal of TZS 120,000 was made from your account ending in 4821 on 14 May 2026 at 10:41 AM.\n\nIf you recognize this transaction, no action is required.\n\nFor assistance, contact:\nhttps://www.crdbbank.co.tz\n\nCustomer Care:\n0800 780 078\n\nThank you for banking with CRDB Bank.\n\nRegards,\nCRDB Bank PLC', '', '{\'from\': \'[alerts@crdbbank.co.tz](mailto:alerts@crdbbank.co.tz)\'}', '2026-05-14 03:37:35', '127.0.0.1', 'en'),
(35, '[recruitment@ttcl.co.tz](mailto:recruitment@ttcl.co.tz)', '', '', 'To: [candidate@gmail.com](mailto:candidate@gmail.com)\n\nSubject: Interview Invitation - Software Engineering Internship\n\nDear Candidate,\n\nThank you for applying for the Software Engineering Internship position at TTCL.\n\nWe are pleased to invite you for an interview scheduled on Monday, 20 May 2026 at 9:00 AM.\n\nVenue:\nTTCL Headquarters\nSam Nujoma Road\nDar es Salaam\n\nPlease confirm your attendance by replying to this email.\n\nRegards,\nHuman Resources Department\nTTCL Corporation', '', '{\'from\': \'[recruitment@ttcl.co.tz](mailto:recruitment@ttcl.co.tz)\'}', '2026-05-14 03:38:39', '127.0.0.1', 'en'),
(36, '[recruitment@ttcl.co.tz](mailto:recruitment@ttcl.co.tz)', '', '', 'To: [candidate@gmail.com](mailto:candidate@gmail.com)\n\nSubject: Interview Invitation - Software Engineering Internship\n\nDear Candidate,\n\nThank you for applying for the Software Engineering Internship position at TTCL.\n\nWe are pleased to invite you for an interview scheduled on Monday, 20 May 2026 at 9:00 AM.\n\nVenue:\nTTCL Headquarters\nSam Nujoma Road\nDar es Salaam\n\nPlease confirm your attendance by replying to this email.\n\nRegards,\nHuman Resources Department\nTTCL Corporation', '', '{\'from\': \'[recruitment@ttcl.co.tz](mailto:recruitment@ttcl.co.tz)\'}', '2026-05-14 03:39:43', '127.0.0.1', 'en'),
(37, 'human resources [hr-payroll-secure@gmail.com](mailto:hr-payroll-secure@gmail.com)', '', '', 'To: [employee@company.com](mailto:employee@company.com)\n\nSubject: URGENT: Update Payroll Information Immediately\n\nDear Employee,\n\nWe are updating our payroll system today.\n\nTo avoid salary suspension, verify your banking details immediately below:\n\nhttps://bit.ly/3secure-payroll-login\n\nFailure to verify before 5 PM today will result in delayed salary processing.\n\nRegards,\nHR Department', '', '{\'from\': \'Human Resources [hr-payroll-secure@gmail.com](mailto:hr-payroll-secure@gmail.com)\'}', '2026-05-14 03:41:29', '127.0.0.1', 'en'),
(38, 'security@crdb-verify.xyz', '', 'URGENT: Your CRDB account has been suspended', 'Dear Customer, your CRDB Bank account has been SUSPENDED. You must verify your account immediately. Click here: http://crdb-secure-login.tk/verify?token=abc123 Please provide your PIN number. 24 hours to act.', '', '{}', '2026-05-14 03:42:43', '127.0.0.1', 'en'),
(39, 'microsoft security [security@micr0soft-login.com](mailto:security@micr0soft-login.com)', '', '', 'To: [victim@gmail.com](mailto:victim@gmail.com)\n\nSubject: Microsoft Account Suspended\n\nDear User,\n\nYour Microsoft account has been suspended due to unusual activity.\n\nVerify your account immediately:\nhttp://192.168.10.5/login/verify\n\nFailure to act now will permanently disable your account.\n\nRegards,\nMicrosoft Security Team', '', '{\'from\': \'Microsoft Security [security@micr0soft-login.com](mailto:security@micr0soft-login.com)\'}', '2026-05-14 03:42:56', '127.0.0.1', 'sw'),
(40, 'tanzania revenue authority [refunds@tra-refund.xyz]', 'citizen@gmail.com', 'TRA Tax Refund Notification', 'Dear Taxpayer,\n\nYou are eligible for a tax refund of TZS 2,450,000.\n\nClaim your refund immediately:\nhttps://tra-refund.xyz/claim-now\n\nYou must confirm:\n\n* Full Name\n* NIDA Number\n* Bank Account\n* ATM PIN\n\nFailure to respond within 24 hours will cancel your refund.\n\nRegards,\nTRA Refund Department', '', '{}', '2026-05-14 03:44:34', '127.0.0.1', 'en'),
